package com.wheelwright.evidence.v2.portfolio;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;
import static com.wheelwright.evidence.v2.portfolio.PortfolioJson.*;
import static org.assertj.core.api.Assertions.*;

/** Production evaluator versus independently replayed tt sources; synthetic membership/terms declared. */
class PortfolioMarkParityTest {
 final JsonNode source;
 PortfolioMarkParityTest()throws Exception{source=JSON.readTree(Files.readString(Path.of("../docs/implementation/api-v2-foundational-2026-10-21/fixtures/ung-mark-source.json")));}
 String instrument(String symbol){return "/v2/instruments/"+UUID.nameUUIDFromBytes(symbol.getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 ObjectNode reference(String suffix){return obj().put("kind","REFERENCE_SOURCE").put("provider","SYNTHETIC_SOURCE_REPLAY").put("reference","urn:synthetic:ung-source:"+suffix).putNull("observedAt").put("qualification","SYNTHETIC_REFERENCE");}
 ObjectNode construction(){var c=obj();var children=array();var root=obj().put("kind","GROUP").put("nodeId","ROOT");root.set("children",children);c.set("composition",root);c.set("evidence",array().add(reference("declared-associated-scope")));int i=0;
  for(var h:source.path("holdings")){var contract=source.path("contracts").get(i);var fill=source.at("/orders/0/legs/"+i+"/fills/0");var quantity=new BigDecimal(h.path("quantity").asText());assertThat(quantity).isEqualByComparingTo(new BigDecimal(fill.path("quantity").asText()));var multiplier=new BigDecimal(h.path("multiplier").asText());var basis=new BigDecimal(fill.path("fill-price").asText()).multiply(quantity).multiply(multiplier);var evidence=array().add(reference("opening-leg-"+i));var leaf=obj().put("nodeId","leg-"+i).put("kind","OPTION").put("side",h.path("quantity-direction").asText().equals("Long")?"LONG":"SHORT").put("quantity",decimal(quantity)).put("unit","CONTRACT").put("currency",contract.path("currency").asText());leaf.set("instrument",link(instrument(h.path("symbol").asText())));var terms=obj().put("right",contract.path("right").asText()).put("strike",contract.path("strike").asText()).put("expiration",contract.path("expiration").asText()).put("currency",contract.path("currency").asText()).put("multiplier",contract.path("multiplier").asText()).put("exerciseStyle",contract.path("exerciseStyle").asText()).put("settlement",contract.path("settlement").asText()).put("adjustment",contract.path("adjustment").asText()).put("payoffApplicability","STANDARD_EQUITY_INTRINSIC").put("qualification","QUALIFIED");terms.set("underlying",link(instrument("UNG")));var delivery=obj().put("kind","SHARES").put("quantity",contract.path("deliverableShares").asText()).putNull("currency");delivery.set("instrument",link(instrument("UNG")));terms.set("deliverable",array().add(delivery));terms.set("evidence",array().add(reference("declared-standard-terms-"+i)));leaf.set("terms",terms);var allocation=obj();allocation.set("basis",metric(basis,"MONEY","USD",fill.path("filled-at").asText(),"DECLARED_ASSOCIATED_FULL_OPENING_FILL","QUALIFIED",evidence,"OPENING_CASH_FLOW"));var inventory=obj().put("quantity",decimal(quantity)).put("side",leaf.path("side").asText());inventory.set("instrument",leaf.path("instrument"));inventory.set("evidence",evidence);allocation.set("inventory",inventory);leaf.set("allocation",allocation);var economics=obj();economics.set("fees",unknown("MONEY",null,"HISTORY_INCOMPLETE"));economics.set("reportedOpenPl",unknown("MONEY",null,"BROKER_EVALUATION_BASIS_UNVERIFIED"));leaf.set("economics",economics);children.add(leaf);i++;
  }return c;
 }
 Map<String,ObjectNode> observations(){var observations=new HashMap<String,ObjectNode>();int i=0;for(var q:source.path("quotes")){var value=obj().put("observedAt",q.path("updated-at").asText());for(String field:List.of("bid","ask","mid","mark"))value.set(field,metric(new BigDecimal(q.path(field).asText()),"PRICE","USD",q.path("updated-at").asText(),"SOURCE_REPORTED_"+field.toUpperCase(Locale.ROOT),"QUALIFIED",array().add(reference("quote-"+i+"-"+field)),"CURRENT_MARKET"));observations.put(instrument(q.path("symbol").asText()),value);i++;}for(var q:source.path("spotQuotes")){var value=obj().put("observedAt",q.path("updated-at").asText());for(String field:List.of("bid","ask","mid","mark"))value.set(field,metric(new BigDecimal(q.path(field).asText()),"PRICE","USD",q.path("updated-at").asText(),"SOURCE_REPORTED_"+field.toUpperCase(Locale.ROOT),"QUALIFIED",array().add(reference("spot-"+field)),"CURRENT_MARKET"));observations.put(instrument(q.path("symbol").asText()),value);}return observations;}
 @Test void completeBrokerMarksReplaceTheWholeInconsistentCreditPackage()throws Exception{var c=construction();var e=PortfolioMath.evaluate(c,observations(),Instant.parse(source.path("now").asText()));assertThat(e.at("/marketValue/method").asText()).isEqualTo("SIGNED_HELD_WHOLE_PACKAGE_BROKER_MARK_SUM");assertThat(e.at("/estimatedClosingCashFlow/value").asText()).startsWith("-");assertThat(e.at("/grossUnrealizedPl/value").isTextual()).isTrue();assertThat(e.at("/netUnrealizedPl/value").isNull()).isTrue();for(var ref:e.at("/marketValue/evidence"))assertThat(ref.path("reference").asText()).doesNotContain("-mid");var directory=Path.of("build/portfolio-mark-parity");Files.createDirectories(directory);Files.writeString(directory.resolve("evaluation.json"),e.toPrettyString());var captures=Path.of("build/portfolio-responses");Files.createDirectories(captures);var capture=obj().put("path","urn:synthetic:portfolio-mark-evaluation").put("schema","Evaluation").put("caller","production-evaluator-synthetic-source-test");capture.set("body",e);Files.writeString(captures.resolve("ung-mark-evaluation.json"),capture.toString());}
 @Test void oneUnusableMarkCannotBeMixedWithOtherLegMidpoints(){var c=construction();var quotes=observations();((ObjectNode)quotes.get(instrument(source.path("holdings").get(0).path("symbol").asText())).path("mark")).putNull("value").put("status","INCOMPLETE");var e=PortfolioMath.evaluate(c,quotes,Instant.parse(source.path("now").asText()));for(String field:List.of("marketValue","estimatedClosingCashFlow","grossUnrealizedPl","netUnrealizedPl")){assertThat(e.path(field).path("value").isNull()).isTrue();assertThat(e.path(field).path("warningCodes").toString()).contains("SOURCE_CONFLICT");}assertThat(number(e.at("/openingCashFlow/value"))).isPositive();assertThat(leaves(c.path("composition"))).hasSize(4);}
 @Test void validMidpointRemainsAuthoritativeWhenMarksDiffer(){var c=construction();var quotes=observations();String symbol=source.path("holdings").get(2).path("symbol").asText();((ObjectNode)quotes.get(instrument(symbol)).path("mid")).put("value","0.36");var e=PortfolioMath.evaluate(c,quotes,Instant.parse(source.path("now").asText()));assertThat(e.at("/marketValue/method").asText()).isEqualTo("SIGNED_HELD_MIDPOINT_SUM");assertThat(number(e.at("/marketValue/value"))).isEqualByComparingTo("-3");}
 @Test void debitStructuresMayHaveAValidPositiveClosingCredit(){var c=construction();for(var n:leaves(c.path("composition")))n.put("side",n.path("side").asText().equals("LONG")?"SHORT":"LONG");var quotes=observations();((ObjectNode)quotes.get(instrument(source.path("holdings").get(2).path("symbol").asText())).path("mid")).put("value","0.36");var e=PortfolioMath.evaluate(c,quotes,Instant.parse(source.path("now").asText()));assertThat(e.at("/marketValue/method").asText()).isEqualTo("SIGNED_HELD_MIDPOINT_SUM");assertThat(number(e.at("/estimatedClosingCashFlow/value"))).isPositive();}
 @Test void spotFreshnessIsIndependentOfTheCurrentOptionPackage(){var c=construction();var quotes=observations();var spot=quotes.get(instrument("UNG"));((ObjectNode)spot.path("mid")).put("asOf","2026-10-10T19:00:00Z");var e=PortfolioMath.evaluate(c,quotes,Instant.parse(source.path("now").asText()));assertThat(e.path("freshness").asText()).isEqualTo("CURRENT");assertThat(e.at("/spot/asOf").asText()).isEqualTo("2026-10-10T19:00:00Z");assertThat(e.at("/spot/warningCodes").toString()).contains("STALE_MARKET_OBSERVATION");}

}
